function fillJetour(){const b=$('car-brand');b.innerHTML='<option value="">Другая марка</option>'+Object.entries(brandNames).map(([v,n])=>`<option value="${v}">${n}</option>`).join('');fillModels();const st=$('service-type');st.innerHTML=Object.entries(jetourService).map(([v,x])=>`<option value="${v}">${x[0]}</option>`).join('')+'<option value="custom">Другая работа</option>'}
function fillModels(){const brand=$('car-brand').value,m=$('jetour-model'),selected=m.value;m.innerHTML=Object.entries(brandModels[brand]||{}).map(([v,n])=>`<option value="${v}">${n}</option>`).join('');if(brandModels[brand]?.[selected])m.value=selected}
function fillPowertrains(){
 const brand=$('car-brand').value,model=$('jetour-model').value,variants=modelVariants[brand+':'+model],select=$('powertrain'),selected=select.value;
 $('powertrain-wrap').hidden=!variants;
 select.innerHTML=variants?Object.entries(variants).map(([value,label])=>`<option value="${value}">${label}</option>`).join(''):'';
 if(variants?.[selected])select.value=selected;
}
function refreshServiceOptions(){
 const brand=$('car-brand').value,model=$('jetour-model').value,variant=$('powertrain').value;
 if(!brandModels[brand]?.[model])return;
 for(const option of $('service-type').options){
  if(option.value!=='custom')option.textContent=serviceFor(brand,model,option.value,variant)[0];
 }
}

