vehicleSpecs['jetour:x70']={title:'JETOUR X70 — данные из официального руководства',source:'официальное руководство эксплуатации JETOUR X70, разделы «Техническое обслуживание» и «Спецификация»',items:['Двигатель SQRE4T15C, 1,5 л Turbo, 1498 см³, 115 кВт; максимальный момент 210 Н·м','Коробка 626DHA (DCT6) или 6MF22A по комплектации; передний привод','Топливо: неэтилированный бензин с октановым числом 95; бак 55 л','Руководство требует выполнять плановое ТО по графику и использовать рекомендованные жидкости; таблица периодичности зависит от комплектации и условий эксплуатации','При тяжёлых условиях моторное масло и масляный фильтр заменяются чаще; фильтры двигателя и кондиционера также требуют сокращённого интервала','Точные заправочные объёмы масла и жидкости коробки нужно сверять с сервисной картой конкретной комплектации, так как руководство X70 содержит несколько вариантов']};
modelServiceNotes['jetour:x70']={1:['Заменить моторное масло и масляный фильтр по сервисной карте X70','Проверить DCT 626DHA/МКПП, тормоза, охлаждение и отсутствие течей'],2:['Заменить салонный фильтр','Проверить воздушный фильтр, ремни, патрубки, радиатор и кондиционер'],3:['Проверить тормозную жидкость и свечи по сроку/пробегу','Проверить подвеску, приводы, рулевое управление и шины'],4:['Проверить уровень жидкости 626DHA/МКПП по комплектации','Проверить тормозную систему, аккумулятор и электронные системы'],5:['Проверить систему охлаждения, ремни и ролики','Проверить коробку, приводы, подвеску и отсутствие течей'],6:['Заменить моторное масло, масляный и салонный фильтры по графику','Проверить тормозную жидкость, свечи, трансмиссию и крепёж'],7:['Проверить воздушный фильтр и систему вентиляции','Проверить тормоза, шины, подвеску, рулевое управление и течи'],8:['Провести расширенный осмотр двигателя и коробки','Проверить все уровни жидкостей, фильтры и электронные системы']};
vehicleSpecs['jetour:x70plus']={title:'JETOUR X70+ — российская комплектация и карта ТО',source:'модель X70+ https://jetour-ru.com/models/x70plus; руководство X70+ https://jetour-ru.com/media-link/x70-plus-rukovodstvo; таблица жидкостей прежнего руководства https://jetour-ru.com/media/download/docs/1CG6gh__7pg6z2-rukovodstvo-po-ekspluatacii-x70-plus.pdf; карта ТО JETOUR Россия https://jetour-ru.com/media-link/service-map',items:['Текущая российская комплектация: SQRF4J16 1.6T 190 л.с., 7G-DCT, передний привод; код коробки определить по табличке или VIN','Для SQRF4J16 прежнее российское руководство указывает C3 5W-30, 4,3 ± 0,2 л; объём уточнять по фактическому уровню после замены с масляным фильтром','На каждом ТО через 10 000 км или 12 месяцев менять моторное масло, масляный и салонный фильтры; воздушный фильтр и DOT4 через 20 000 км, свечи через 30 000 км, охлаждающую жидкость через 40 000 км','Красная органическая охлаждающая жидкость −40 °C; точный объём для текущей комплектации не опубликован. DOT4: в таблице прежнего руководства для автоматической коробки 0,8 ± 0,05 л','Топливный фильтр в баке — замена через 90 000 км; артикулы фильтров и свечей выбирать по VIN','Актуальная российская модельная страница: бензин АИ-95, бак 57 л; в старой таблице жидкостей указан бак 55 л, поэтому для модели 2026 использовать данные актуальной страницы'],variantItems:{'unknown':['Код 7DCT пока не указан. Перед заменой определить DF727A или 738DHA; жидкости и интервалы не взаимозаменяемы','Для DF727A: BOT351 C4, справочная ёмкость 4,8 ± 0,1 л; замена через 40 000 км или 48 месяцев','Для 738DHA: Kunlun DCTF 7S, справочная ёмкость 6,5 ± 0,2 л; замена через 60 000 км или 72 месяца'],'df727a':['Код коробки DF727A: BOT351 C4, справочная ёмкость 4,8 ± 0,1 л; замена через 40 000 км или 48 месяцев','Уровень после сервисной замены выставлять по процедуре; справочную ёмкость не считать точным объёмом слива'],'738dha':['Код коробки 738DHA: Kunlun DCTF 7S, справочная ёмкость 6,5 ± 0,2 л; замена через 60 000 км или 72 месяца','Уровень после сервисной замены выставлять по процедуре; справочную ёмкость не считать точным объёмом слива']}};
vehicleSpecs['jetour:t2']={title:'JETOUR T2 — российская версия 2.0T AWD',source:'JETOUR Россия: https://jetour-ru.com/models/t2 ; карта ТО: https://jetour-ru.com/media-link/service-map ; руководство: https://jetour-ru.com/media-link/t2-manual',items:['Двигатель SQRF4J20: 2,0 л, 245 л.с.; тип и объём моторного масла сверить с руководством и VIN','Комплектации Люкс и Престиж: 7DCT 740DHB; Премиум: 8AT 840AHA','На каждом ТО: моторное масло и масляный фильтр, салонный фильтр','Воздушный фильтр и тормозная жидкость — через 20 000 км / 24 месяца; свечи — через 30 000 км / 36 месяцев; охлаждающая жидкость — через 40 000 км / 48 месяцев','Раздаточная коробка AWD — замена масла через 40 000 км / 48 месяцев; задний дифференциал и муфта 4WD — через 60 000 км / 72 месяца','Точные марки и заправочные объёмы жидкостей AWD сверить по VIN и сервисной документации; заправочная ёмкость может отличаться от объёма сервисной замены'],variantItems:{'7dct':['7DCT 740DHB: замена трансмиссионной жидкости через 60 000 км / 72 месяца; тип и сервисный объём подтвердить по VIN'],'8at':['8AT 840AHA: замена ATF через 50 000 км / 60 месяцев; тип и сервисный объём подтвердить по VIN']}};
vehicleSpecs['jetour:dashing']={title:'JETOUR DASHING — актуальные российские версии',source:'JETOUR Россия: https://jetour-ru.com/models/dashing ; руководство: https://jetour-ru.com/media-link/dashing-manual ; карта ТО: https://jetour-ru.com/media-link/service-map',items:['Выберите двигатель и коробку: 1.5T/6DCT/2WD или 1.6T/8AT/AWD; обе версии рассчитаны на бензин АИ-95, бак 57 л','На каждом ТО: моторное масло и масляный фильтр, салонный фильтр','Воздушный фильтр и тормозная жидкость — через 20 000 км / 24 месяца; свечи — через 30 000 км / 36 месяцев; охлаждающая жидкость — через 40 000 км / 48 месяцев','Заправочная ёмкость коробки может отличаться от объёма сервисной замены; фактический уровень выставлять по процедуре'],variantItems:{'15dct':['SQRE4T15C: масло двигателя с фильтром SM 5W-30 — 4,7 ± 0,2 л по руководству DASHING','6DCT260: Sinopec DCTF-GS, справочная ёмкость 3,6 ± 0,1 л; замена через 60 000 км / 72 месяца','Охлаждающая жидкость −40 °C: для 6DCT260 в руководстве указано 9,5 л; тормозная жидкость DOT4'],'16at':['SQRF4J16C: объём и допуск моторного масла именно этой версии подтвердить по VIN; прежний объём для SQRF4J16 без суффикса C сюда не переносится','8AT 830AHA: замена ATF через 50 000 км / 60 месяцев; тип и сервисный объём подтвердить по VIN','AWD: масло раздаточной коробки, заднего дифференциала и муфты меняется через 50 000 км / 60 месяцев; марки и объёмы подтвердить по VIN']}};
vehicleSpecs['jetour:x50']={title:'JETOUR X50 — руководство и карта ТО официального дилера',source:'руководство JETOUR X50, стр. 176–178; https://jetour-ru.com/media-link/x50-manual; карта ТО официального дилера JETOUR У Сервис+ https://www.jetour-uservice.ru/owners/reglament/x50/',items:['Первое напоминание об обслуживании — 5 000 км; плановая таблица дилера: ТО-1 — ТО-8 через каждые 10 000 км или 12 месяцев','На каждом ТО: моторное масло и масляный фильтр, салонный фильтр; воздушный фильтр — каждые 20 000 км, свечи — каждые 30 000 км','Тормозная жидкость — каждые 20 000 км или 24 месяца, охлаждающая — каждые 40 000 км или 48 месяцев','Бензин: неэтилированный АИ-92 и выше; бак 45 л по руководству X50','Российское руководство X50 не публикует заправочные объёмы и допуски моторного и трансмиссионного масел. Перед заменой подтвердить их по VIN и сервисной документации; уровень выставлять по процедуре'],variantItems:{'15mt':['Атмосферный SQRE4G15C 1.5 л, 113 л.с.; коробка 5MF17J-AD (5MT)','Масло 5MT: замена каждые 30 000 км или 36 месяцев по карте дилера; точный тип и объём для российской версии не опубликованы'],'15dct':['Турбированный SQRE4T15C 1.5T, 147 л.с.; коробка 6DCT260 (6DCT)','Жидкость 6DCT: замена каждые 50 000 км или 60 месяцев по карте дилера; точный тип и объём для российской версии не опубликованы']}};
modelServiceNotes['jetour:x50']={1:['Заменить моторное масло и масляный фильтр по карте 1.5 MPI или 1.5T','Проверить 5MT/6DCT, тормоза, охлаждение и отсутствие течей'],2:['Заменить салонный фильтр CN95','Проверить воздушный фильтр, ремни, радиаторы и кондиционер'],3:['Проверить тормозную жидкость и свечи по сроку/пробегу','Проверить подвеску, рулевое управление, приводы и шины'],4:['Проверить уровень масла 5MT или жидкости 6DCT по модификации','Проверить тормоза, аккумулятор и электронные системы'],5:['Проверить систему охлаждения, патрубки, ремни и ролики','Проверить трансмиссию, подвеску и отсутствие течей'],6:['Заменить масло и фильтры по графику; тормозную жидкость по сроку','Проверить 5MT/6DCT, тормоза, крепёж и датчики'],7:['Проверить воздушный фильтр и вентиляцию картера','Проверить тормоза, шины, подвеску, рулевое управление и течи'],8:['Провести расширенный осмотр двигателя и коробки','Проверить все уровни жидкостей, фильтры и электронные системы']};
vehicleSpecs['jetour:x90plus']={title:'JETOUR X90+ — руководство и карта ТО JETOUR Россия',source:'официальное руководство X90+, стр. 186–192; https://jetour-ru.com/media/download/docs/sfPLWe__rukovodstvo-po-ekspluatacii-x90-plus.pdf; карта ТО JETOUR Россия https://jetour-ru.com/media-link/service-map; комплектации https://jetour-ru.com/models/x90plus',items:['ТО-1 — ТО-8: каждые 10 000 км или 12 месяцев; в тяжёлых условиях руководство требует обслуживание каждые 5 000 км или 6 месяцев','На каждом ТО менять моторное масло, масляный и салонный фильтры; воздушный фильтр — через 20 000 км, свечи — через 30 000 км','Тормозная жидкость DOT4 — через 20 000 км или 24 месяца по карте JETOUR; охлаждающая жидкость — через 40 000 км или 48 месяцев','Топливный фильтр в баке — через 90 000 км; номер фильтра и остальных деталей подбирать по VIN','Перед заменой масла коробки обязательно определить код агрегата: DF727A и 738DHA требуют разные жидкости и интервалы'],variantItems:{'16dct':['Двигатель SQRF4J16 1.6T: Castrol SN/SP 5W-30, 4,3 ± 0,2 л при замене с масляным фильтром','Охлаждающая жидкость: красная органическая −40 °C, 9,0 ± 0,3 л','Для DF727A: BOT351 C4, 4,8 ± 0,1 л по таблице руководства; замена через 40 000 км или 48 месяцев по карте ТО','Для 738DHA: Kunlun DCTF-7S, 6,5 ± 0,2 л по таблице руководства; замена через 60 000 км или 72 месяца по карте ТО','Объёмы коробок в руководстве справочные: фактическую заливку выполнять по сервисной процедуре и коду коробки'],'20dct':['Двигатель SQRF4J20 2.0T: Fuchs C5 0W-20, 4,0 ± 0,1 л при замене с масляным фильтром','Охлаждающая жидкость: красная органическая −40 °C, 10,4 ± 0,2 л','Для DF727A: BOT351 C4, 4,8 ± 0,1 л; замена через 40 000 км или 48 месяцев','Для 738DHA: Kunlun DCTF-7S, 6,5 ± 0,2 л; замена через 60 000 км или 72 месяца','Перед заменой определить код коробки по автомобилю; заправочный объём не равен автоматически сервисному сливу'],'20at':['Российская комплектация 2026 года: двигатель 2.0T, 8AT и полный привод; код двигателя и коробки подтвердить по VIN','Если установлен SQRF4J20: руководство X90+ указывает Fuchs C5 0W-20, 4,0 ± 0,1 л с фильтром и охлаждающую жидкость 10,4 ± 0,2 л','Карта ТО JETOUR: для коробок 830AHA/840AHA замена ATF через 50 000 км или 60 месяцев; код установленной 8AT подтвердить до применения интервала','Руководство X90+ не публикует тип и сервисный объём жидкости новой 8AT AWD, раздатки, заднего дифференциала и муфты; сверить по VIN','Для X90+ AWD карта ТО задаёт замену масла раздатки через 50 000 км и масел заднего дифференциала/муфты через 60 000 км; точные жидкости и объёмы сверить по VIN']}};
vehicleSpecs['jetour:t1']={title:'JETOUR T1 — российская бензиновая версия 2.0T 8AT XWD',source:'JETOUR Россия: https://jetour-ru.com/models/t1 ; карта ТО: https://jetour-ru.com/media-link/service-map ; руководство: https://jetour-ru.com/media-link/t1-manual',items:['Двигатель SQRF4J20: 2,0 л, 245 л.с., 375 Н·м; бензин не ниже АИ-95, бак 70 л','Восьмиступенчатая автоматическая коробка 840AHA и полный привод XWD','На каждом ТО: моторное масло и масляный фильтр, салонный фильтр','Воздушный фильтр и тормозная жидкость — через 20 000 км / 24 месяца; свечи — через 30 000 км / 36 месяцев; охлаждающая жидкость — через 40 000 км / 48 месяцев','ATF 8AT — через 50 000 км / 60 месяцев; масло раздаточной коробки — через 40 000 км / 48 месяцев; масла заднего дифференциала и муфты — через 60 000 км / 72 месяца','Точные допуски и сервисные объёмы моторного масла, ATF и агрегатов XWD сверить по VIN и руководству T1; данные другой модели переносить нельзя']};
vehicleSpecs['bestune:b70']={title:'FAW BESTUNE B70 New — данные официального руководства',source:'руководство FAW BESTUNE B70 New, стр. 345–349 и 441–445; https://cdn.perxis.ru/originals/cudp19obeucc7390nlkg/original',items:['Первое ТО: 5 000 км или 6 месяцев; затем таблица ТО через каждые 10 000 км','Воздушный фильтр: очистка через 10 000 км и замена через 30 000 км; фильтр кондиционера — каждые 12 месяцев или 20 000 км','Свечи зажигания: замена через 30 000 км; топливный фильтр и DOT4 — каждые 2 года или 40 000 км','Картридж угольного фильтра: каждые 2 года или 30 000 км; охлаждающая жидкость — каждые 5 лет или 100 000 км','Тормозная жидкость DOT4: справочная ёмкость 0,92 ± 0,05 л'],variantItems:{'15dct':['1.5T CA4GB15TD-30: масло 5W-30 — 4,8 л при замене масла и фильтра; 5,2 л после полного опорожнения','Двигатель 1.5T: масло и фильтр после первого ТО через 10 000 км; таблица для первых 60 000 км также указывает 6 месяцев — придерживаться более раннего срока','7DCT: BOT 351 C4 — полная ёмкость 7,2 ± 0,1 л; совместная замена жидкости и фильтра высокого давления 5,7 ± 0,1 л через 40 000 км или 4 года','Охлаждающая жидкость: 7,2 ± 0,5 л; свечи: 3707010A27L'],'20at':['2.0T CA4GC20TD-36: масло 5W-30 — 5,3 л при замене масла и фильтра; 6,0 ± 0,1 л после полного опорожнения','Двигатель 2.0T: масло и фильтр после первого ТО каждые 10 000 км или 12 месяцев','6AT: AW-1; таблица ТО указывает замену через 60 000 км, раздел спецификаций — только при необходимости. Перед работой сверить сервисную книжку и процедуру; объём сервисной замены не указан','Охлаждающая жидкость: 7,6 ± 0,5 л; свечи: ILZKAR8M7S']}};
vehicleSpecs['faw:b70']=vehicleSpecs['bestune:b70'];
const bestuneOilAdvisory='Обновлённая рекомендация BESTUNE от 04.08.2026 для CA4GB15TD-30 и CA4GC20TD-36: SAE 5W-30 с ACEA C3 (или выше) / GF-6A. При прежнем интервале 10 000 км производитель временно рекомендует замену через 7 000–8 000 км; если руководство уже требует 5 000 км, соблюдать более короткий интервал. Источник: https://bestune.ru/brand/news/bestune-update-recommendations-for-engine-oils/';
vehicleSpecs['bestune:t55'].items.push(bestuneOilAdvisory);
vehicleSpecs['bestune:t77'].items.push(bestuneOilAdvisory);
vehicleSpecs['bestune:t90'].variantItems['15dct'].push(bestuneOilAdvisory);
vehicleSpecs['bestune:b70'].variantItems['15dct'].push(bestuneOilAdvisory);
vehicleSpecs['bestune:b70'].variantItems['20at'].push(bestuneOilAdvisory);
const bestuneDctCalibration='Калибровать блок клапанов и сцепление 7DCT при плановом ТО специализированным оборудованием BESTUNE';
const bestuneDctCalibrationNote='7DCT: при каждом плановом ТО требуется калибровка блока клапанов и сцепления; источник: https://bestune.ru/brand/news/diagnostics-of-the-bestune-model-range/';
vehicleSpecs['bestune:t55'].items.push(bestuneDctCalibrationNote);
const t77DctSpec=vehicleSpecs['bestune:t77'].items.find(x=>x.startsWith('7DCT:'));
const t77MtSpec=vehicleSpecs['bestune:t77'].items.find(x=>x.startsWith('В руководстве также указаны МКП'));
vehicleSpecs['bestune:t77'].items=vehicleSpecs['bestune:t77'].items.filter(x=>x!==t77DctSpec&&x!==t77MtSpec);
